def VTask.memPartition {α : Type u_1} (f : ℕ → Set α) (n : ℕ) : Set (Set α) :=
match n with
| 0 => {univ}
| n + 1 =>
  let prev_partition := VTask.memPartition f n;
  let rec split_partition (ps : Set (Set α)) : Set (Set α) :=
    match ps with
    | empty_set => empty_set
    | insert p ps' =>
      let p_f_n := p ∩ f n;
      let p_f_nc := p \ f n;
      insert p_f_n (insert p_f_nc (split_partition ps'))
  split_partition prev_partition
